require_once __DIR__ . '/_layout.php';requirePermission('maintenance.manage');
if(requestMethod()==='POST'){requireCsrfPost();$action=$_POST['action']??'';try{if($action==='status'){$record=dbFetchOne('SELECT m.*,v.agency_id FROM maintenance_records m JOIN vehicles v ON v.id=m.vehicle_id WHERE m.id=:id',['id'=>(int)$_POST['id']]);if(!$record)throw new InvalidArgumentException(t('validation.maintenance_not_found'));requireAgencyAccess($record['agency_id']);$status=validateChoice($_POST['status']??'',['scheduled','in_progress','completed','cancelled'],'');if(!$status)throw new InvalidArgumentException(t('validation.maintenance_status'));withTransaction(function()use($record,$status){dbExecute('UPDATE maintenance_records SET status=:status,entry_at=IF(:s2=\'in_progress\',COALESCE(entry_at,NOW()),entry_at),actual_exit_at=IF(:s3=\'completed\',NOW(),actual_exit_at),updated_by=:user WHERE id=:id',['status'=>$status,'s2'=>$status,'s3'=>$status,'user'=>currentUserId(),'id'=>$record['id']]);if($status==='in_progress')dbExecute("UPDATE vehicles SET status='maintenance',updated_by=:user WHERE id=:id",['user'=>currentUserId(),'id'=>$record['vehicle_id']]);elseif(in_array($status,['completed','cancelled'],true))dbExecute("UPDATE vehicles SET status='available',updated_by=:user WHERE id=:id AND status='maintenance'",['user'=>currentUserId(),'id'=>$record['vehicle_id']]);});auditLog('maintenance.status_changed','maintenance_record',$record['id'],['status'=>$record['status']],['status'=>$status],$record['agency_id']);flash('success',t('message.maintenance_status_updated'));}}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Maintenance operation failed');flash('danger',t('message.maintenance_failed'));}safeRedirect('maintenance.php');}
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$vehicleFilter=(int)($_GET['vehicle_id']??0);if($vehicleFilter&&!dbFetchOne("SELECT id FROM vehicles WHERE id=? AND agency_id IN ($ph) AND archived_at IS NULL",array_merge([$vehicleFilter],$ids)))$vehicleFilter=0;$recordSql="SELECT m.*,v.registration_number,v.brand,v.model FROM maintenance_records m JOIN vehicles v ON v.id=m.vehicle_id WHERE v.agency_id IN ($ph) AND m.archived_at IS NULL";$recordParams=$ids;$documentSql="SELECT vd.*,v.registration_number FROM vehicle_documents vd JOIN vehicles v ON v.id=vd.vehicle_id WHERE v.agency_id IN ($ph) AND vd.archived_at IS NULL";$documentParams=$ids;if($vehicleFilter){$recordSql.=' AND m.vehicle_id=?';$recordParams[]=$vehicleFilter;$documentSql.=' AND vd.vehicle_id=?';$documentParams[]=$vehicleFilter;}$records=dbFetchAll($recordSql.' ORDER BY COALESCE(m.scheduled_date,DATE(m.entry_at)) DESC LIMIT 100',$recordParams);$documents=dbFetchAll($documentSql.' ORDER BY vd.expires_at LIMIT 100',$documentParams);
backofficeHeader(t('nav.maintenance'),'maintenance.php');?><?php pageHeader('page.maintenance.title', 'page.maintenance.description', ['breadcrumbs'=>[['label'=>'nav.fleet'],['label'=>'nav.maintenance']],'primary'=>['label'=>'action.save_maintenance','href'=>'maintenance_form.php']]); ?><div class="grid"><section class="card full"><div class="section-card-header"><h2><?=navigationIcon('fleet')?><?=e(t('section.maintenance_register'))?></h2></div><div class="table-wrap"><table><tr><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.schedule'))?></th><th><?=e(t('field.cost'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($records as $r):?><tr><td><bdi><?=e($r['registration_number'])?></bdi></td><td><?=e(t('option.'.$r['maintenance_type']))?></td><td><?=formattedDate($r['scheduled_date'])?><br><?=formattedDateTime($r['entry_at'])?> → <?=formattedDateTime($r['estimated_exit_at'])?></td><td><?=money($r['cost'])?></td><td><form method="post"><?=csrfField()?><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=e($r['id'])?>"><select name="status" onchange="this.form.submit()"><?php foreach(['scheduled','in_progress','completed','cancelled'] as $s):?><option value="<?=e($s)?>" <?=$s===$r['status']?'selected':''?>><?=e(translatedStatus($s))?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?></table><?php if(!$records)echo emptyState('empty.no_records');?></div><div class="section-card-header stacked"><h2><?=navigationIcon('document')?><?=e(t('section.document_expiration'))?></h2><?=primaryAction('action.store_document','vehicle_document_form.php',['class'=>'compact'])?></div><div class="table-wrap"><table><tr><th><?=e(t('field.vehicle'))?></th><th><?=e(t('field.document'))?></th><th><?=e(t('field.expires'))?></th><th><?=e(t('field.alert'))?></th></tr><?php foreach($documents as $d):$days=$d['expires_at']?(new DateTimeImmutable('today'))->diff(new DateTimeImmutable($d['expires_at']))->format('%r%a'):null;?><tr><td><bdi><?=e($d['registration_number'])?></bdi></td><td><?=e(t('option.'.$d['document_type']))?></td><td><?=formattedDate($d['expires_at'])?></td><td><?=is_numeric($days)&&$days<=30?statusBadge($days<0?'expired':'pending'):''?></td></tr><?php endforeach;?></table><?php if(!$documents)echo emptyState('empty.no_records');?></div></section></div><?php backofficeFooter();
